const form = document.querySelector('#due');
const year = form.querySelector('#year');
const month = form.querySelector('#month');
const day = form.querySelector('#day');
const fill = (select, values) => select.replaceChildren(...values.map(value => {
  const option = document.createElement('option');
  option.value = value;
  option.textContent = value;
  return option;
}));
fill(year, Array.from({length: 201}, (_, i) => 1900 + i));
year.value = new Date().getFullYear();
fill(month, Array.from({length: 12}, (_, i) => i + 1));
function refreshDays() {
  const previous = Number(day.value) || 1;
  const count = new Date(Number(year.value), Number(month.value), 0).getDate();
  fill(day, Array.from({length: count}, (_, i) => i + 1));
  day.value = Math.min(previous, count);
}
year.addEventListener('change', refreshDays);
month.addEventListener('change', refreshDays);
refreshDays();
form.addEventListener('submit', () => {
  form.elements.dueDate.value = `${year.value}-${month.value.padStart(2, '0')}-${day.value.padStart(2, '0')}`;
});

